"""TrialCounter —— harness 追加、agent 不可写的试验计数器 (p3 §4.2)。

裁决继承:
- 唯一写入口 = register_trial(params) (actor=harness), append-only JSONL;
- count() = 行计数 + 序号连续性校验 (删行/改行即序号断裂 → TrialCountFraudError);
- 报告 N ≠ 计数器 N 即 TrialCountFraudError; N 缺失直接抛错
  ("未报 N 一文不值" 的代码形状);
- 计数域覆盖一切遴选性计算: 参数网格、因子筛选、IC 估计、每次策略运行
  (BacktestEngine.run 自动 register_trial);
- N ≥ 300 为下界: P3 项目累计 EXP-001(120)+EXP-003(24)+EXP-004(156)=300,
  任何后续 DSR 的 N = baseline(300) + 本地新增计数。

"agent 不可写" 的工程形状 (单机版 RCON 等价通道③):
- 文件只以 append 模式打开, 类不提供任何删改 API;
- 每行携带 {"n": 序号, "actor": "harness", "params": ...} —— 规范 JSON,
  行序号从 1 连续递增; count() 每次全量校验连续性与 actor 字段,
  任何外部篡改 (删行/改 actor/乱序) 都会被抓;
- 无墙钟、无随机 (确定性契约 §4.3)。
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Mapping

from quant_engine.errors import TrialCountFraudError
from quant_engine.event_bus import canonical_json
from quant_engine.validation.constants import (
    TRIAL_COUNT_FLOOR,
    assert_thresholds_sealed,
)


class TrialCounter:
    """append-only 试验计数器 (harness 写, agent 只读)。"""

    ACTOR = "harness"

    def __init__(self, path: str | Path, baseline: int | None = None) -> None:
        assert_thresholds_sealed()
        self._path = Path(path)
        self._path.parent.mkdir(parents=True, exist_ok=True)
        # baseline: 项目累计下界 (默认 = TRIAL_COUNT_FLOOR = 300, p3 §4.2 实录;
        # 只可 ≥ 下界, 传更小值即拒 —— 下界不可配低)
        base = TRIAL_COUNT_FLOOR if baseline is None else int(baseline)
        if base < TRIAL_COUNT_FLOOR:
            raise TrialCountFraudError(
                f"baseline 不得低于项目累计下界 {TRIAL_COUNT_FLOOR}: {base}"
            )
        self._baseline = base

    @property
    def path(self) -> Path:
        return self._path

    @property
    def baseline(self) -> int:
        return self._baseline

    # ---- 唯一写入口 (actor=harness, append-only) ----

    def register_trial(self, params: Mapping[str, Any]) -> int:
        """追加一次试验, 返回新的本地计数 (harness 唯一写入口)。"""
        n = self._local_count() + 1
        row = {"n": n, "actor": self.ACTOR, "params": dict(params)}
        with self._path.open("a", encoding="utf-8", newline="\n") as fh:
            fh.write(canonical_json(row) + "\n")
        return n

    # ---- 只读口径 (含篡改执法) ----

    def _local_count(self) -> int:
        """本地行计数 + 连续性/actor 校验 (篡改即 TrialCountFraudError)。"""
        if not self._path.exists():
            return 0
        lines = [
            ln for ln in self._path.read_text(encoding="utf-8").splitlines()
            if ln.strip()
        ]
        for i, ln in enumerate(lines, start=1):
            try:
                row = json.loads(ln)
            except json.JSONDecodeError as exc:
                raise TrialCountFraudError(
                    f"计数器第 {i} 行损坏 (疑似篡改): {exc}"
                ) from exc
            if int(row.get("n", -1)) != i:
                raise TrialCountFraudError(
                    f"计数器序号断裂: 第 {i} 行 n={row.get('n')} (疑似删改)"
                )
            if row.get("actor") != self.ACTOR:
                raise TrialCountFraudError(
                    f"计数器第 {i} 行 actor={row.get('actor')!r} ≠ 'harness' "
                    "(agent 不可写)"
                )
        return len(lines)

    def count(self) -> int:
        """有效试验数 N = baseline(项目累计下界) + 本地新增。"""
        return self._baseline + self._local_count()

    # ---- 执法: 报告 N 必须等于计数器 N ----

    def enforce_reported_n(self, reported_n: int | None) -> int:
        """DSR 前置执法: N 缺失或 ≠ 计数器 N 即 TrialCountFraudError。

        返回经执法的 N (= 计数器口径), 供 DSR 计算使用。
        """
        actual = self.count()
        if reported_n is None:
            raise TrialCountFraudError(
                "未报 N 的回测一文不值: DSR 计算必须携带试验计数 (p3 §4.2)"
            )
        if int(reported_n) != actual:
            raise TrialCountFraudError(
                f"试验计数造假被抓: 报告 N={reported_n} ≠ 计数器 N={actual}"
            )
        return actual

"""OosRegistry —— OOS 一次性评估, 看过即烧毁 (p3 §4.3)。

裁决继承:
- 每张实验卡开卡时预注册 IS/OOS 切分, 落盘时间早于任何 OOS 数据读取;
- OOS 评估登记后二次评估抛 OosSpentError;
- 无论 OOS 结果如何 oos_consumed=true 永久烧毁 (先烧毁后评估:
  评估函数抛异常同样算已消耗 —— "看过" 的判据是解封, 不是成功);
- 三件套过线才有资格申请 OOS (由 gates.validate_run 编排, 本类只执法一次性)。

持久化: JSONL append-only (与 TrialCounter 同款纪律); 状态跨进程有效 ——
同一 registry 文件下任何进程二次评估同一卡即被抓。
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Callable, Mapping

from quant_engine.errors import OosSpentError
from quant_engine.event_bus import canonical_json


class OosRegistry:
    """OOS 一次性评估登记簿 (append-only)。"""

    def __init__(self, path: str | Path) -> None:
        self._path = Path(path)
        self._path.parent.mkdir(parents=True, exist_ok=True)

    @property
    def path(self) -> Path:
        return self._path

    # ---- 内部: 读全量状态 ----

    def _rows(self) -> list[dict[str, Any]]:
        if not self._path.exists():
            return []
        return [
            json.loads(ln)
            for ln in self._path.read_text(encoding="utf-8").splitlines()
            if ln.strip()
        ]

    def _append(self, row: Mapping[str, Any]) -> None:
        with self._path.open("a", encoding="utf-8", newline="\n") as fh:
            fh.write(canonical_json(dict(row)) + "\n")

    # ---- 开卡: 预注册 IS/OOS 切分 (落盘先于取数) ----

    def register_split(
        self, card_id: str, is_range: str, oos_range: str
    ) -> None:
        """预注册切分; 重复注册同卡即抛 (切分不可改, 改切分=换卡)。"""
        for row in self._rows():
            if row.get("card_id") == card_id and row.get("op") == "split":
                raise OosSpentError(
                    f"实验卡 {card_id} 的 IS/OOS 切分已注册, 不可改 (p3 §4.3)"
                )
        self._append(
            {
                "op": "split",
                "card_id": card_id,
                "is_range": is_range,
                "oos_range": oos_range,
                "oos_consumed": False,
            }
        )

    def is_consumed(self, card_id: str) -> bool:
        return any(
            row.get("card_id") == card_id and row.get("op") == "consume"
            for row in self._rows()
        )

    def is_registered(self, card_id: str) -> bool:
        return any(
            row.get("card_id") == card_id and row.get("op") == "split"
            for row in self._rows()
        )

    # ---- 一次性评估 ----

    def evaluate_once(
        self, card_id: str, evaluate: Callable[[], Any]
    ) -> Any:
        """OOS 评估 (唯一入口): 未注册切分即拒; 已消耗即 OosSpentError;
        先烧毁 (落盘 consume 行) 后评估 —— 无论评估结果/异常, OOS 永久作废。
        """
        if not self.is_registered(card_id):
            raise OosSpentError(
                f"实验卡 {card_id} 未预注册 IS/OOS 切分, OOS 不解封 (p3 §4.3)"
            )
        if self.is_consumed(card_id):
            raise OosSpentError(
                f"OOS 已烧毁: 实验卡 {card_id} 的 OOS 段只许评估一次 (p3 §4.3)"
            )
        # 先烧毁后评估: "看过" 的判据是解封动作本身
        self._append({"op": "consume", "card_id": card_id,
                      "oos_consumed": True})
        return evaluate()

"""引擎共享异常。

规格回指:
- 任务书 §4.3 确定性契约 / p3_stack_design.md §2.1:
  - 数据句柄"时间戳单调强制，倒流即抛错" → TimeTravelError
  - "FILL_TIMING=next_open 为构造常量，改为其他值即抛 LookaheadError"
    (LookaheadError 在 ENG-2 execution/ 使用, 异常类型在 ENG-1 先行定义,
    clock/data 的时点纪律违规同样以其表达前视语义)
"""

from __future__ import annotations


class QuantEngineError(Exception):
    """引擎异常基类。"""


class TimeTravelError(QuantEngineError):
    """时间倒流: 时钟或数据游标被要求回退到过去 (p3_stack_design.md §2.1 数据句柄行)。"""


class LookaheadError(QuantEngineError):
    """前视违规: 试图读取 > t 时点才可用的数据, 或篡改 FILL_TIMING 构造常量 (§2.1 执行行)。"""


class ValidationError(QuantEngineError):
    """ENG-4 验证层异常基类 (p3_stack_design.md §4 验证与过拟合防线)。"""


class TrialCountFraudError(ValidationError):
    """试验计数造假: 报告 N ≠ 计数器 N, 或 N 缺失 (p3 §4.2: 未报 N 一文不值;
    计数器 harness 追加, agent 不可写)。"""


class OosSpentError(ValidationError):
    """OOS 已烧毁: OOS 段为一次性资源, 登记后二次评估即抛 (p3 §4.3:
    无论结果如何 oos_consumed=true 永久烧毁)。"""

"""CostModel —— taker 10bp + 滑点 5bp 悲观默认档, 只可上调。

规格回指:
- 任务书 §4.1 costs/: "成本模型: taker 10bp + 滑点 5bp 悲观默认档, 只可上调"
- p3_stack_design.md §2.1 执行行: "成本默认悲观档 = taker 10bp + 滑点 5bp,
  成本参数只能上调不可低于默认档进入裁决"
- 任务书 ENG-2: "成本只可上调 (DEFAULT → PESSIMISTIC → EXTREME), 不可下调;
  calculate_cost(price, qty, side) → (fee, slippage, total_cost);
  成本档位入 config 与运行产物"

执法形状:
- 档位与费率为类级常量 (代码常量, 非运行时可变配置);
- 构造时任何低于 DEFAULT 档费率的定制一律抛 CostFloorError;
- 运行中只允许 escalate() 到更高档, 不存在任何下调路径 (方法不提供)。
"""

from __future__ import annotations

from enum import Enum

from quant_engine.errors import QuantEngineError

BP = 1e-4  # 1 basis point


class CostFloorError(QuantEngineError):
    """成本试图低于悲观默认档 (p3 §2.1: 不可低于默认档进入裁决)。"""


class CostTier(str, Enum):
    """成本档位, 数值只增不减 (DEFAULT → PESSIMISTIC → EXTREME)。"""

    DEFAULT = "DEFAULT"
    PESSIMISTIC = "PESSIMISTIC"
    EXTREME = "EXTREME"


# 档位 → (taker 费率 bp, 滑点 bp)。DEFAULT 即 p3 定稿悲观档 taker10bp+滑点5bp。
TIER_BP: dict[CostTier, tuple[float, float]] = {
    CostTier.DEFAULT: (10.0, 5.0),
    CostTier.PESSIMISTIC: (20.0, 10.0),
    CostTier.EXTREME: (50.0, 25.0),
}

_TIER_ORDER: dict[CostTier, int] = {
    CostTier.DEFAULT: 0,
    CostTier.PESSIMISTIC: 1,
    CostTier.EXTREME: 2,
}


class CostModel:
    """成交成本模型 (bar 级 L1, 全部按 taker 计 —— 悲观口径)。

    - fee = notional × taker_bp; slippage = notional × slippage_bp
      (滑点以成本额记账, 成交价保持 bar 口径原价, fill ledger 分列 fee/slippage);
    - 限价单成交价受限价界约束, 滑点项由撮合层决定是否计入
      (v1 悲观口径: 市价单计滑点, 限价单以限价为界不另计滑点, 费率仍按 taker);
    - 定制费率只允许 ≥ 所选档位费率 (更悲观), 低于 DEFAULT 档一律 CostFloorError。
    """

    def __init__(
        self,
        tier: CostTier | str = CostTier.DEFAULT,
        taker_bp: float | None = None,
        slippage_bp: float | None = None,
    ) -> None:
        self._tier = CostTier(tier)
        base_taker, base_slip = TIER_BP[self._tier]
        floor_taker, floor_slip = TIER_BP[CostTier.DEFAULT]
        self._taker_bp = float(taker_bp) if taker_bp is not None else base_taker
        self._slippage_bp = (
            float(slippage_bp) if slippage_bp is not None else base_slip
        )
        if self._taker_bp < floor_taker or self._slippage_bp < floor_slip:
            raise CostFloorError(
                f"成本不可低于悲观默认档 taker≥{floor_taker}bp/滑点≥{floor_slip}bp: "
                f"got taker={self._taker_bp}bp slippage={self._slippage_bp}bp"
            )
        if self._taker_bp < base_taker or self._slippage_bp < base_slip:

#!/usr/bin/env node
/**
 * K3 golden-case runner (`make golden`). Iterates k3/golden/<CASE>/case.json and executes each
 * case's declared command. A case failing = nonzero exit. Case files are regression assets:
 * the test-read-only discipline covers them (three_domains.md бь5.5).
 */
import { execSync } from "node:child_process";
import { readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..", "..");
const cases = readdirSync(here).filter((d) => {
	try {
		return statSync(join(here, d)).isDirectory();
	} catch {
		return false;
	}
});

let failed = 0;
for (const dir of cases.sort()) {
	const specPath = join(here, dir, "case.json");
	let spec;
	try {
		spec = JSON.parse(readFileSync(specPath, "utf8"));
	} catch {
		console.error(`[k3-golden] ${dir}: missing/invalid case.json`);
		failed += 1;
		continue;
	}
	console.log(`[k3-golden] running ${spec.case_id} (${spec.domain}) бн`);
	try {
		execSync(spec.command, { cwd: repoRoot, stdio: "inherit", shell: "/bin/bash" });
		console.log(`[k3-golden] ${spec.case_id}: PASS`);
	} catch {
		console.error(`[k3-golden] ${spec.case_id}: FAIL`);
		failed += 1;
	}
}
if (cases.length === 0) console.log("[k3-golden] no cases registered");
process.exit(failed === 0 ? 0 : 1);

