 *                     advances only when the ledger PROVES the work happened. The mechanical
 *                     layer (this file + predicates.ts) is a no-LLM deterministic program; the
 *                     judgment layer (review.ts) is a context-free review subagent. If L1 can
 *                     decide, L2 is never consulted — the expensive layer only sees what the
 *                     cheap layer cannot decide (§4.2.3).
 * - Axiom binding   : Axiom 9 (push architected); Axiom 1/2 via §4.2.8 (mechanical predicates
 *                     check actions, not reasoning); Axiom 5 (every verdict is a fsynced ledger
 *                     row — gate.* is in FSYNC_PREFIXES); Axiom 6 (denominator floors: small-n
 *                     ratios are unevaluable, → HOLD).
 * - Deprecation     : four-valued verdicts fold HOLD→FAIL under unattended runs, but the fold
 *                     itself is ledgered (payload.folded_from, §4.2.2). The L1 short-circuit is
 *                     deprecable only if total per-eval cost drops below gate-management
 *                     overhead (§4.2.10). The denominator floor is NOT deprecable (statistical
 *                     bottom line). Registry entries retire per §4.2.9 (100% pass rate for N
 *                     rounds with untouched criteria → advisory → retired).
 *
 * DECLARATION SURFACE = ENFORCEMENT SURFACE: the registry is a static literal in this file —
 * no settings read, no env read, no agent-writable config. W1 already lists `k3/gates` in
 * PROTECTED_DENY_WRITE; `installK3StageGate` (index.ts) asserts that seam at install time.
 */

import type { EventLedger } from "../ledger/event-ledger.js";
import {
	ALL_L1_PREDICATES,
	type GateVerdict,
	INTENSIVE_INVARIANTS,
	type L1Context,
	type L1Predicate,
	type PredicateResult,
	VERDICT_SEVERITY,
} from "./predicates.js";
import type { L2Reviewer, L2ReviewOutcome } from "./review.js";

export type { GateVerdict } from "./predicates.js";

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

export class GateRegistryError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "GateRegistryError";
	}
}

/** Risk R4: a FAIL-KILL traced to an uncalibrated threshold is a bug in the gate itself. */
export class ProvisionalThresholdError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "ProvisionalThresholdError";
	}
}

// ---------------------------------------------------------------------------
// Five-tuple registry (§4.2.1) — static literals, never configuration
// ---------------------------------------------------------------------------

/**
 * Metrics marked critical: a single breach is a global FAIL-KILL (G5, Kayenta criticalIncrease).
 * LITERAL CONSTANT — no dynamic injection path; the k3-stage-gate test asserts the shape and
 * §4.2.1 forbids relaxation ("threshold_set 中标记 critical 的项属安全边界，静态永不放宽").
 */
export const CRITICAL_METRICS: readonly string[] = [
	"boundary_violations", // P8
	"canary_triggered", // Q4 / W4 apparatus
	"ledger_chain_broken", // Q3
	"verifier_failed", // P4
	"active_direct_write", // Q5
	"verify_artifact_failed", // Q6
];

export interface GateSpec {
	readonly gate_id: string;
	/** ≥2 mutually balancing metrics (anti-Goodhart, §4.2.5). */
	readonly metric_set: readonly string[];
	/** Threshold descriptors; calibration state governs FAIL-KILL eligibility (risk R4). */
	readonly threshold_set: readonly {
		readonly metric: string;
		readonly critical: boolean;
		readonly provisional: boolean;
	}[];
	/** Measurement window (events / clock / candidates). */
	readonly window: string;
	/** Responsible verifier (name + version → L1/L2/L3 attribution). */
	readonly verifier: string;
	/** Four-value → successor action mapping is fixed by §4.2.2; this names the escalation path. */
	readonly escalation: string;
	/** Governance fields, registered separately from criteria (§4.2.1). */
	readonly approval: "auto" | "dual-sign";
	readonly blocking: boolean;
}

/**
 * The K3 gate table. Criteria changes are themselves candidates and must pass a higher gate
 * (§4.4); editing this literal is a source-code change that must survive `make verify` and the
 * W4 invariants suite.
 */
