	{
		gate_id: "tool_call.admission",
		metric_set: ["boundary_violations", "phase_quota"],
		threshold_set: [
			{ metric: "boundary_violations", critical: true, provisional: false },
			{ metric: "phase_quota", critical: false, provisional: true }, // PROVISIONAL: 待 GAP-058 标定
		],
