/** Runs the playbook set in order; a failing playbook NEVER throws — it reports pass:false. */
export async function runTripwires(env: TripwireEnv, ids?: readonly string[]): Promise<TripwireOutcome[]> {
	const selected = ids === undefined ? TRIPWIRE_PLAYBOOKS : TRIPWIRE_PLAYBOOKS.filter((p) => ids.includes(p.id));
	const outcomes: TripwireOutcome[] = [];
	for (const pb of selected) {
		try {
			outcomes.push(await pb.run(env));
		} catch (err) {
			outcomes.push({
				id: pb.id,
				title: pb.title,
				intercepted: false,
				ledgered: false,
				pass: false,
				detail: `playbook crashed: ${err instanceof Error ? err.message : String(err)}`,
			});
		}
	}
	return outcomes;
}

function zeroFloors(): ExtensiveFloors {
	return {
