// ---------------------------------------------------------------------------
// Scan helpers
// ---------------------------------------------------------------------------

function walkTsFiles(dir: string, acc: string[] = []): string[] {
	if (!existsSync(dir)) return acc;
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		const p = join(dir, entry.name);
		if (entry.isDirectory()) walkTsFiles(p, acc);
		else if (entry.name.endsWith(".ts")) acc.push(p);
	}
	return acc;
}

function k3SourceFiles(ctx: InvariantContext): string[] {
	return walkTsFiles(join(ctx.pkgRoot, "src", "k3"));
}

function readText(path: string): string | null {
	return existsSync(path) ? readFileSync(path, "utf8") : null;
}

/** True when a `/` at this position opens a regex literal rather than a division operator. */
function startsRegexLiteral(emitted: string): boolean {
	const prev = emitted.replace(/\s+$/, "").slice(-1);
	return prev === "" || "(,=:[!&|?{};+*%~^<>".includes(prev);
}

/** Index just past the closing `/` (plus flags) of a regex literal starting at `start`. */
function regexLiteralEnd(text: string, start: number): number {
	let i = start + 1;
	let inClass = false;
	while (i < text.length) {
		const ch = text[i];
		if (ch === "\\") {
			i += 2;
			continue;
		}
		if (ch === "\n") return start; // unterminated: not a regex literal after all
		if (ch === "[") inClass = true;
		else if (ch === "]") inClass = false;
		else if (ch === "/" && !inClass) {
			i += 1;
			while (i < text.length && /[a-z]/.test(text[i])) i += 1;
			return i;
		}
		i += 1;
	}
	return start;
}

/**
 * Blanks out comments and string/template literals while PRESERVING line numbers, so the source
 * scans judge CODE SHAPE and not prose. Without this, an invariant that names the shape it
 * forbids would flag its own documentation бк and the honest fix is to scan code, not to weaken
 * the pattern (a scanner that cannot describe what it forbids is a scanner nobody maintains).
 */
export function codeOnly(text: string): string {
	let out = "";
	let i = 0;
	const n = text.length;
	let mode: "code" | "line" | "blockcomment" | "'" | '"' | "`" = "code";
	while (i < n) {
		const ch = text[i];
		const next = text[i + 1];
		if (mode === "code") {
			if (ch === "/" && next === "/") {
				mode = "line";
				out += "  ";
				i += 2;
				continue;
			}
			if (ch === "/" && next === "*") {
				mode = "blockcomment";
				out += "  ";
				i += 2;
				continue;
			}
			if (ch === "'" || ch === '"' || ch === "`") {
				mode = ch;
				out += " ";
				i += 1;
				continue;
			}
			// Regex literals must be skipped too: a quote inside a character class would otherwise
			// open a phantom string and desync the whole scan (the failure that made this scanner
			// flag its own pattern table on the first run).
			if (ch === "/" && startsRegexLiteral(out)) {
				const end = regexLiteralEnd(text, i);
				if (end > i) {
					out += " ".repeat(end - i);
					i = end;
					continue;
				}
			}
			out += ch;
			i += 1;
			continue;
		}
		if (mode === "line") {
			if (ch === "\n") {
				mode = "code";
				out += "\n";
			} else out += " ";
			i += 1;
			continue;
		}
		if (mode === "blockcomment") {
			if (ch === "*" && next === "/") {
				mode = "code";
				out += "  ";
				i += 2;
				continue;
			}
			out += ch === "\n" ? "\n" : " ";
			i += 1;
			continue;
		}
		// inside a string / template literal
		if (ch === "\\") {
			out += "  ";
			i += 2;
			continue;
		}
		if (ch === mode) {
			mode = "code";
			out += " ";
			i += 1;
			continue;
		}
		out += ch === "\n" ? "\n" : " ";
		i += 1;
	}
	return out;
}

/**
 * Walks RUNTIME imports (type-only imports create no call-graph edge) starting at entry files.
 * Shared by I7; identical semantics to the W3 inline scan it absorbs.
 */
export function runtimeImportClosure(entryFiles: readonly string[]): Map<string, string[]> {
	const edges = new Map<string, string[]>();
	const queue = [...entryFiles];
	while (queue.length > 0) {
		const file = queue.pop() as string;
		if (edges.has(file)) continue;
		const text = readText(file);
		if (text === null) {
			edges.set(file, []);
			continue;
		}
		const specifiers: string[] = [];
		const importRe = /(^|\n)\s*(import|export)\s+([^;]*?)from\s+["']([^"']+)["']/g;
		for (const m of text.matchAll(importRe)) {
			const clause = m[3];
			const spec = m[4];
			if (/^\s*type[\s{]/.test(clause)) continue;
			specifiers.push(spec);
			if (spec.startsWith(".")) queue.push(resolve(dirname(file), spec.replace(/\.js$/, ".ts")));
		}
		edges.set(file, specifiers);
	}
	return edges;
}

