/**
 * The I3 scan body, exposed separately so the M6 mutation detector can run the SAME static check
 * against a synthesized source form (H3 tier of the GAP-059 kill record).
 */
export function scanHandlerAssignments(files: readonly (readonly [string, string])[]): string[] {
	const offenders: string[] = [];
	const tableMark = "HostRequest" + "Handlers"; // split so this file never marks itself
	for (const [name, raw] of files) {
		if (!raw.includes(tableMark)) continue;
		const text = codeOnly(raw);
		const lines = text.split("\n");
		// Variables that ARE a dispatch table: declared with the table type, or conventionally
		// named `handlers`. Assignments into anything else are not registrations.
		const tables = new Set<string>(["handlers"]);
		for (const m of text.matchAll(new RegExp(`(?:const|let|var)\\s+(\\w+)\\s*:\\s*${tableMark}`, "g"))) {
			tables.add(m[1]);
		}
		for (let i = 0; i < lines.length; i++) {
			const line = lines[i];
			const assignment = /(\w+)\[[^\]]+\]\s*=[^=]/.exec(line);
			if (assignment === null) continue;
			if (!tables.has(assignment[1])) continue;
			if (line.includes("withDomainGuard(") || line.includes("denyingHandler(")) continue;
			offenders.push(`${name}:${i + 1}: handler-table assignment does not go through withDomainGuard`);
		}
	}
	return offenders;
}

