/** Runs every invariant; never throws бк the TEST surface asserts offenders == []. */
export function runInvariants(ctx: InvariantContext, ids?: readonly string[]): InvariantResult[] {
	const selected = ids === undefined ? K3_INVARIANTS : K3_INVARIANTS.filter((i) => ids.includes(i.id));
	return selected.map((inv) => {
		const offenders = inv.check(ctx);
		return { id: inv.id, title: inv.title, kind: inv.kind, offenders, ok: offenders.length === 0 };
	});
}

/**
 * LOAD-TIME enforcement: a violated invariant refuses the load. Called by
 * `installK3CanaryApparatus` before anything else is wired бк a canary apparatus whose own
 * invariants fail must not arm itself (Axiom 9 obligation 5 applied reflexively).
 */
export function assertInvariantsAtLoad(ctx: InvariantContext, ids?: readonly string[]): InvariantResult[] {
	const results = runInvariants(ctx, ids);
	const violated = results.filter((r) => !r.ok);
	if (violated.length > 0) {
		const detail = violated.map((v) => `${v.id} ${v.title}:\n  ${v.offenders.join("\n  ")}`).join("\n");
		throw new InvariantViolationError(
			`K3 canary apparatus refuses to load: ${violated.length} invariant(s) violated\n${detail}`,
			results,
		);
	}
	return results;
}

/**
 * K3 implant бд W4-T4 бд canary L4 бк evaluation-asset layer: GUID contamination sentinels,
 * sentinel tasks, and seeded-defect calibration (бь4.3.5; Decision 4 option D).
 *
 * COMPONENT TRIPLE (verification_kernel.md бь4.3.8)
 * - Reason to exist : sealed (leak PREVENTION) and canary (leak DETECTION) cover OPPOSITE
 *                     failure modes; a sealed split cannot tell you that it already leaked.
 *                     BIG-bench-style GUID sentinels can: reproduction of the GUID IS the proof.
 * - Axiom binding   : Axiom 6 (empirical), Axiom 9 obligation 5.
 * - Deprecation     : if K3 never uses an externally leakable eval set, the whole layer is
 *                     deprecable бк WITH a ledger row recording the decision.
 *
 * ASSET DISCIPLINE (бь4.3.5): this layer is NOT a unit-test surface. The corpus lives under
 * `k3/canary/**` which W1 lists in PROTECTED_DENY_READ + PROTECTED_DENY_WRITE, is maintained by
 * an OUT-OF-LOOP process, and is never described body-first in any document (this file holds
 * generators and checks, never canary bodies; бь4.3.5(e) anti-fingerprinting).
 *
 * THE TWO RATES ARE NEVER MERGED (бь4.3.5(c)): `calibrate()` reports hand_seeded and mutant
 * detection rates SEPARATELY and refuses to compute any difference or average of them; the
 * ledger row carries `source б╩ {hand_seeded, mutant}`. The 60% / 84.50% figures from the
 * source material are evidence that the two injection sources have DIFFERENT DIFFICULTY
 * DISTRIBUTIONS бк not evidence that either source is the better verifier probe.
 *
 * CALIBRATION IS NOT AN ADMISSION SCORE (бь4.3.5(d)): the output is a verifier-health claim
 * (`claim.verifier_health`), a different claim type from candidate quality.
 */

import { createHash, randomUUID } from "node:crypto";
import type { AppendResult, EventLedger } from "../ledger/event-ledger.js";
import type { Allowlist } from "../security/allowlist.js";
import { PROTECTED_DENY_READ } from "../security/allowlist.js";

// ---------------------------------------------------------------------------
// GUID sentinels
// ---------------------------------------------------------------------------

/**
 * Prefix of the sentinel marker. Deliberately generic and rotated per corpus generation so the
 * marker itself is not a stable fingerprint (бь4.3.5(e); honeytoken fingerprinting research).
 */
const SENTINEL_PREFIX = "k3-canary-guid";

export interface GuidSentinel {
	readonly sentinel_id: string;
	/** The GUID whose reproduction proves leakage. */
	readonly guid: string;
	/** Where the sentinel was planted (corpus path or asset name). */
	readonly planted_in: string;
	/** Generation counter for the rotation discipline. */
	readonly generation: number;
	/** Opaque reference used in ledger rows бк the BODY never enters the ledger (Decision 2). */
	readonly ref: string;
}

/** Mints a GUID sentinel. The full marker string is the leak probe; the ref is its hash. */
export function mintGuidSentinel(plantedIn: string, generation = 1, guid: string = randomUUID()): GuidSentinel {
	const marker = `${SENTINEL_PREFIX}:${guid}`;
	return {
		sentinel_id: `sent_${createHash("sha256").update(marker).digest("hex").slice(0, 12)}`,
		guid,
		planted_in: plantedIn,
		generation,
		ref: `sha256:${createHash("sha256").update(marker).digest("hex")}`,
	};
}

/** The exact string planted into the asset. Kept out of ledger payloads by discipline. */
export function sentinelMarker(sentinel: GuidSentinel): string {
	return `${SENTINEL_PREFIX}:${sentinel.guid}`;
}

export interface LeakFinding {
	readonly sentinel_id: string;
	readonly ref: string;
	readonly where: string;
}

/**
 * Scans candidate-produced text for planted sentinels. A hit is PROOF of leakage: the model
 * could not have produced the GUID without having read the asset.
 */
export function detectLeaks(
	texts: readonly { readonly where: string; readonly text: string }[],
	sentinels: readonly GuidSentinel[],
): LeakFinding[] {
	const findings: LeakFinding[] = [];
	for (const sentinel of sentinels) {
		const marker = sentinelMarker(sentinel);
		for (const candidate of texts) {
			if (candidate.text.includes(marker) || candidate.text.includes(sentinel.guid)) {
				findings.push({ sentinel_id: sentinel.sentinel_id, ref: sentinel.ref, where: candidate.where });
			}
		}
	}
	return findings;
}

/**
 * Ledgers a leak as an OPAQUE hard event: `canary.leak_detected` carries the sentinel REF only.
 * Together with `canaryTrippedPredicate` (tripwire.ts) this makes the leak a critical FAIL-KILL
 * without handing the agent any detail it could reverse-engineer (бь4.3.6 rule 4).
 */
export function recordLeak(ledger: EventLedger, phase: string, finding: LeakFinding): AppendResult {
	return ledger.append({
		event_type: "canary.leak_detected",
		actor: { role: "canary_runner" },
		action: "escalate",
		phase,
		payload: { sentinel_ref: finding.ref, where: finding.where, verdict: "FAIL-KILL" },
		idem_key: null,
	});
}

// ---------------------------------------------------------------------------
// Sentinel tasks бк "must never pass" / "must never fail" (бь4.3.5(b))
// ---------------------------------------------------------------------------

export type SentinelTaskKind = "impossible" | "trivial";

export interface SentinelTask {
	readonly task_id: string;
	readonly kind: SentinelTaskKind;
	/** Expected outcome; an impossible task passing (or a trivial one failing) is corruption. */
	readonly expected: "fail" | "pass";
}

export interface SentinelTaskObservation {
	readonly task_id: string;
	readonly observed: "fail" | "pass";
}

export interface EvalCorruptionVerdict {
	readonly corrupt: boolean;
	readonly verdict: "PASS" | "FAIL-KILL";
	readonly anomalies: readonly string[];
	/** True when the selection gate must be frozen (бь4.3.5(b)). */
	readonly freeze_selection_gate: boolean;
}

/**
 * Judges sentinel-task outcomes. An impossible task that "passed" means the candidate is
 * over-fitting / cheating / reading leaked answers б· FAIL-KILL and freeze the selection gate.
 */
export function judgeSentinelTasks(
	tasks: readonly SentinelTask[],
	observations: readonly SentinelTaskObservation[],
): EvalCorruptionVerdict {
	const anomalies: string[] = [];
	for (const task of tasks) {
		const obs = observations.find((o) => o.task_id === task.task_id);
		if (obs === undefined) {
			anomalies.push(`${task.task_id}: no observation (a sentinel task that never ran cannot vouch for the eval)`);
			continue;
		}
		if (obs.observed !== task.expected) {
			anomalies.push(
				`${task.task_id}: ${task.kind} sentinel expected ${task.expected} but observed ${obs.observed} бк eval corruption`,
			);
		}
	}
	const corrupt = anomalies.length > 0;
	return {
		corrupt,
		verdict: corrupt ? "FAIL-KILL" : "PASS",
		anomalies,
		freeze_selection_gate: corrupt,
	};
}

// ---------------------------------------------------------------------------
// Seeded-defect calibration бк two rates, reported SEPARATELY (бь4.3.5(c))
// ---------------------------------------------------------------------------

export type InjectionSource = "hand_seeded" | "mutant";

export interface SeededDefect {
	readonly defect_id: string;
	readonly source: InjectionSource;
	/** Whether the verifier flagged it. */
	readonly detected: boolean;
}

export interface SourceRate {
	readonly source: InjectionSource;
	readonly injected: number;
	readonly detected: number;
	readonly rate: number;
}

export class RateMergeError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "RateMergeError";
	}
}

/**
 * Per-source detection rates. Mixing the injection sources is MANDATORY (both must be present:
 * hand-seeded defects and mutants have different difficulty distributions), and merging the
 * resulting rates is FORBIDDEN бк `mergedRate()` exists only to throw, so any caller that tries
 * gets a named error instead of a plausible number.
 */
export function calibrationRates(defects: readonly SeededDefect[]): readonly SourceRate[] {
	const sources: InjectionSource[] = ["hand_seeded", "mutant"];
	const present = sources.filter((s) => defects.some((d) => d.source === s));
	if (present.length < 2) {
		throw new RateMergeError(
			`calibration requires BOTH injection sources (hand_seeded + mutant); got ${present.join(", ") || "none"} ` +
				`бк бь4.3.5(c) mixed-source discipline`,
		);
	}
	return sources.map((source) => {
		const set = defects.filter((d) => d.source === source);
		const detected = set.filter((d) => d.detected).length;
		return { source, injected: set.length, detected, rate: set.length === 0 ? 0 : detected / set.length };
	});
}

/** Guard rail: the two rates are never subtracted, averaged, or merged (бь4.3.5(c)). */
export function mergedRate(_rates: readonly SourceRate[]): never {
	throw new RateMergeError(
		"the hand_seeded and mutant detection rates must never be merged, averaged or subtracted " +
			"(бь4.3.5(c)): the two injection sources have different difficulty distributions, so any " +
			"combined number is uninterpretable",
	);
}

export interface CalibrationReport {
	readonly rates: readonly SourceRate[];
	/** Verifier-health claim type бк NOT a candidate admission score (бь4.3.5(d)). */
	readonly claim_type: "claim.verifier_health";
	readonly below_floor: readonly InjectionSource[];
}

/**
 * Runs the calibration and ledgers one `canary.calibration` row PER SOURCE (each row carries its
 * own `source` field, so no reader can accidentally aggregate them).
 */
export function calibrate(
	ledger: EventLedger,
	phase: string,
	defects: readonly SeededDefect[],
	floor = 0.8, // PROVISIONAL: ┤¤ GAP-058 ▒ъ╢и
): CalibrationReport {
	const rates = calibrationRates(defects);
	for (const r of rates) {
		ledger.append({
			event_type: "canary.calibration",
			actor: { role: "canary_runner" },
			action: "calibrate",
			phase,
			payload: {
				source: r.source,
				injected: r.injected,
				detected: r.detected,
				rate: r.rate,
				floor,
				claim_type: "claim.verifier_health", // never claim.candidate_quality (бь4.3.5(d))
			},
			idem_key: null,
		});
	}
	return {
		rates,
		claim_type: "claim.verifier_health",
		below_floor: rates.filter((r) => r.rate < floor).map((r) => r.source),
	};
}

