// Rotation discipline (бь4.3.5(e)) and corpus hiding (G9)
// ---------------------------------------------------------------------------

export interface SentinelHistory {
	readonly sentinel_id: string;
	/** Consecutive cycles in which this instance was detected. */
	readonly consecutive_detections: number;
}

export interface RotationPlan {
	readonly retire: readonly string[];
	readonly keep: readonly string[];
	readonly reason: string;
}

/**
 * A sentinel detected 3 cycles in a row is retired to the archive and replaced by a NEW surface
 * form of the same category (anti-memorization). Retirement is a ledgered archive move, never a
 * deletion.
 */
export function planRotation(history: readonly SentinelHistory[], threshold = 3): RotationPlan {
	const retire = history.filter((h) => h.consecutive_detections >= threshold).map((h) => h.sentinel_id);
	return {
		retire,
		keep: history.filter((h) => h.consecutive_detections < threshold).map((h) => h.sentinel_id),
		reason: `instances detected ${threshold}+ consecutive cycles are memorized; rotate surface form (бь4.3.5(e))`,
	};
}

export class CorpusExposureError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "CorpusExposureError";
	}
}

/**
 * G9 enforcement for the asset layer: the corpus root must be inside PROTECTED_DENY_READ and
 * unreachable through the agent allowlist. Called at load; a reachable corpus refuses the load
 * (the detector must be hidden from the optimised бк DGM: objective hacking rises when the
 * evaluation functions are visible).
 */
export function assertCorpusHidden(corpusRoot: string, allowlist?: Allowlist): void {
	if (!PROTECTED_DENY_READ.some((p) => corpusRoot === p || corpusRoot.startsWith(`${p}/`))) {
		throw new CorpusExposureError(
			`canary corpus root "${corpusRoot}" is not covered by PROTECTED_DENY_READ ` +
				`(${PROTECTED_DENY_READ.join(", ")}); G9 requires the detector to be unreadable by the optimised`,
		);
	}
	if (allowlist?.checkPath(corpusRoot, "read").allowed === true) {
		throw new CorpusExposureError(
			`canary corpus root "${corpusRoot}" is readable through allowlist "${allowlist.version}"; ` +
				`declaration surface (deny-read prefix) must equal enforcement surface`,
		);
	}
}

/**
 * Out-of-loop maintenance assertion: the corpus writer identity must NOT be the optimised agent
 * (бь4.3.6 rule 4 бк the canary library is maintained by a process outside the loop).
 */
export function assertOutOfLoopMaintainer(writerRole: string): void {
	if (writerRole === "prime_agent" || writerRole === "subagent") {
		throw new CorpusExposureError(
			`role "${writerRole}" may not maintain the canary corpus; maintenance is an out-of-loop process ` +
				`(бь4.3.6 rule 4) бк otherwise the optimised writes its own detector`,
		);
	}
}

/**
