/** The four-valued gate decision (§4.2.2). There is deliberately no fifth value. */
export type GateVerdict = "PASS" | "FAIL-KILL" | "HOLD" | "RECYCLE";

/**
 * Severity order for conjunction folding (§4.2.5): a critical breach outranks a redoable
 * failure, which outranks "cannot evaluate", which outranks pass. RECYCLE > HOLD because a
 * decisive, fixable failure already prescribes the next action (redo the phase) — redoing also
 * re-collects whatever made other criteria unevaluable; HOLD alone prescribes only waiting.
 */
export const VERDICT_SEVERITY: Readonly<Record<GateVerdict, number>> = {
	"FAIL-KILL": 3,
	RECYCLE: 2,
	HOLD: 1,
	PASS: 0,
};

export interface PredicateResult {
	/** Stable predicate id (P1–P9, Q1–Q7). */
	readonly id: string;
	/** Human-readable one-liner of what was checked. */
	readonly check: string;
	readonly ok: boolean;
	/** Verdict this predicate contributes when violated (§4.2.4 tables). */
	readonly verdict_on_fail: GateVerdict;
	/**
	 * True when the threshold behind this predicate is uncalibrated (GAP-058). Provisional
	 * thresholds are ADVISORY: they may contribute HOLD/RECYCLE but the gate hard-asserts they
	 * never produce FAIL-KILL (implementation_phase_plan risk R4).
	 */
	readonly provisional: boolean;
	/** Machine-readable reason code; REQUIRED whenever verdict_on_fail is HOLD (§4.2.2). */
	readonly reason_code: string;
	/** Free-form measurement detail (counts, paths, thresholds actually used). */
	readonly detail: string;
}

function result(
	id: string,
	check: string,
	ok: boolean,
	verdictOnFail: GateVerdict,
	provisional: boolean,
	reasonCode: string,
	detail: string,
): PredicateResult {
	return { id, check, ok, verdict_on_fail: verdictOnFail, provisional, reason_code: reasonCode, detail };
}

