/** The repo-relative gate-table home. MUST stay inside PROTECTED_DENY_WRITE (W1 allowlist.ts). */
export const GATES_HOME = "k3/gates";

/** Seam бд declaration = enforcement: refuse to install a gate whose table home is agent-writable. */
export function assertGatesPathProtected(dir: string = GATES_HOME, repoRoot?: string): void {
	const candidates = [dir];
	if (repoRoot && dir.startsWith(repoRoot)) candidates.push(dir.slice(repoRoot.length).replace(/^[/\\]/, ""));
	const covered = PROTECTED_DENY_WRITE.some((prefix) => candidates.some((c) => pathHasPrefix(c, prefix)));
	if (!covered) {
		throw new LedgerValidationError(
			`gate table home ${dir} is not covered by PROTECTED_DENY_WRITE (${PROTECTED_DENY_WRITE.join(", ")}); ` +
				`a gate whose criteria the agent can rewrite is not a gate`,
		);
	}
}

export interface InstallK3StageGateOptions {
	/** W2 event ledger бк verdict write side. */
	readonly ledger: EventLedger;
	/** Ledger directory бк predicate read side. */
	readonly ledgerDir: string;
	/** W1 allowlist; when provided, install refuses if the agent domain can write `k3/gates`. */
	readonly allowlist?: Allowlist;
	readonly reviewer?: L2Reviewer;
	readonly unattended?: boolean;
	readonly repoRoot?: string;
	readonly now?: () => number;
}

/**
 * Single installation contract: gates-home deny-write assertion б· allowlist enforcement check б·
 * registry well-formedness (inside the StageGate constructor) б· gate. Like W1/W2, there is no
 * `enabled` flag and no off switch.
 */
export function installK3StageGate(options: InstallK3StageGateOptions): StageGate {
	assertGatesPathProtected(GATES_HOME, options.repoRoot);
	if (options.allowlist) {
		const decision = options.allowlist.checkPath(GATES_HOME, "write", options.repoRoot);
		if (decision.allowed) {
			throw new LedgerValidationError(
				`allowlist grants agent-domain write on ${GATES_HOME}; the gate refuses to install ` +
					`until the enforcement surface matches the declaration surface`,
			);
		}
	}
	return new StageGate({
		ledger: options.ledger,
		ledgerDir: options.ledgerDir,
		reviewer: options.reviewer,
		unattended: options.unattended,
		now: options.now,
	});
